// python-base fixture: a clean Python follower passes with the real pinned Ruff (downloaded + sha256-verified into the
// standards cache); each injected defect fails naming its file.
import fs from 'node:fs';
import path from 'node:path';

const MAIN = `"""Fixture app."""

import sys


def first(items: list[str]) -> str:
    return items[0] if items else ""


if __name__ == "__main__":
    sys.stdout.write(first(sys.argv[1:]) + "\\n")
`;

export const fixture = {
  id: 'python-base',
  profiles: ['base@1.0.0', 'python-base@2.0.0'],
  files: {
    '.gitignore': '.ruff_cache/\n__pycache__/\n',
    '.python-version': '3.12\n',
    'uv.lock': 'version = 1\nrequires-python = ">=3.11"\n',
    'pyproject.toml': '[project]\nname = "fixture"\nversion = "0.0.0"\nrequires-python = ">=3.11"\n\n[tool.uv]\nrequired-version = "==0.13.8"\n',
    'ruff.toml': '# fixture overrides\nextend = ".standards/python-base/ruff.toml"\n',
    'app/main.py': MAIN,
  },
  inject: (dir, h) => {
    const put = (rel, body) => { fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true }); fs.writeFileSync(path.join(dir, rel), body); };
    const rm = (rel) => fs.rmSync(path.join(dir, rel));
    const strip = (s) => s.replace(/\x1b\[[0-9;]*m/g, '');

    // uv rules U1-U4: each defect fails naming its file; negatives pass
    const keep = (rel) => fs.readFileSync(path.join(dir, rel));
    const uvCases = [
      ['U1', 'a missing uv.lock', () => { const b = keep('uv.lock'); rm('uv.lock'); return () => fs.writeFileSync(path.join(dir, 'uv.lock'), b); }, /\[python-base\/uv\] pyproject\.toml: U1 /],
      ['U2', 'a requirements.txt', () => { put('requirements.txt', 'requests==2.0.0\n'); return () => rm('requirements.txt'); }, /\[python-base\/uv\] requirements\.txt: U2 /],
      ['U2', 'a nested requirements-dev.txt', () => { put('docs/requirements-dev.txt', 'x==1\n'); return () => rm('docs/requirements-dev.txt'); }, /\[python-base\/uv\] docs\/requirements-dev\.txt: U2 /],
      ['U2', 'a poetry.lock', () => { put('poetry.lock', '# poetry\n'); return () => rm('poetry.lock'); }, /\[python-base\/uv\] poetry\.lock: U2 /],
      ['U2', 'a setup.py without an allow', () => { put('setup.py', '# legacy\n'); return () => rm('setup.py'); }, /\[python-base\/uv\] setup\.py: U2 /],
      ['U3', 'a missing .python-version', () => { const b = keep('.python-version'); rm('.python-version'); return () => fs.writeFileSync(path.join(dir, '.python-version'), b); }, /\[python-base\/uv\] \.python-version: U3 /],
      ['U3', 'a .python-version that is not 3.N', () => { const b = keep('.python-version'); put('.python-version', 'cpython-3.12\n'); return () => fs.writeFileSync(path.join(dir, '.python-version'), b); }, /\[python-base\/uv\] \.python-version: U3 /],
      ['U4', 'a missing required-version', () => { const b = keep('pyproject.toml'); put('pyproject.toml', b.toString().replace(/\n\[tool\.uv\]\nrequired-version = .*\n/, '')); return () => fs.writeFileSync(path.join(dir, 'pyproject.toml'), b); }, /\[python-base\/uv\] pyproject\.toml: U4 /],
      ['U4', 'a required-version that is a range', () => { const b = keep('pyproject.toml'); put('pyproject.toml', b.toString().replace('==0.13.8', '>=0.13')); return () => fs.writeFileSync(path.join(dir, 'pyproject.toml'), b); }, /\[python-base\/uv\] pyproject\.toml: U4 .*not an exact/],
    ];
    for (const [id, what, apply, re] of uvCases) {
      const undo = apply();
      const r = h.check();
      h.step(r.code === 1 && re.test(strip(r.out)), `${what} fails ${id}`, `exit ${r.code}\n${r.out}`);
      undo();
    }
    put('requirements.txt', '# This file was autogenerated by uv via the following command:\n#    uv export --no-hashes\nrequests==2.0.0\n');
    put('legacy/setup.py', '# standards-allow U2: legacy build shim kept for an external tool\n');
    let u = h.check();
    h.step(u.code === 0, 'a `uv export` requirements.txt and a `# standards-allow U2:` setup.py pass', u.out);
    put('legacy/setup.py', '# standards-allow U2\n');
    u = h.check();
    h.step(u.code === 1 && /legacy\/setup\.py: U2 /.test(strip(u.out)), 'an allow without a reason fails U2', u.out);
    rm('requirements.txt');
    rm('legacy/setup.py');
    fs.rmSync(path.join(dir, 'legacy'), { recursive: true });
    const cases = [
      ['app/unused.py', 'import os\n', (o) => /app[\\/]unused\.py:1:\d+: F401/.test(o) && /FAIL \[python-base\/ruff 0\.17\.4 check\]/.test(o), 'an unused import fails ruff check naming app/unused.py:1'],
      ['app/mut.py', 'def f(x=[]):\n    return x\n', (o) => /app[\\/]mut\.py:1:\d+: B006/.test(o), 'a mutable default argument (bugbear) fails naming app/mut.py'],
      ['app/old.py', 'from typing import Optional\n\n\ndef f(x: Optional[int]) -> int:\n    return x or 0\n', (o) => /app[\\/]old\.py:\d+:\d+: (UP045|UP007)/.test(o), 'a legacy Optional[...] (pyupgrade) fails naming app/old.py'],
      ['app/blanket.py', 'import json  # noqa\n\njson.dumps({})\n', (o) => /app[\\/]blanket\.py:1:\d+: PGH004/.test(o), 'a blanket `# noqa` fails PGH004 naming app/blanket.py'],
      ['app/stale.py', 'x = 1  # noqa: F401\n', (o) => /app[\\/]stale\.py:1:\d+: RUF100/.test(o), 'an unused `# noqa: F401` fails RUF100 naming app/stale.py'],
      ['app/ugly.py', 'x = {  "a":1 }\n', (o) => /FAIL \[python-base\/ruff 0\.17\.4 format\]/.test(o) && /app[\\/]ugly\.py/.test(strip(o)), 'an unformatted file fails ruff format --check naming app/ugly.py'],
    ];
    for (const [rel, body, ok, msg] of cases) {
      put(rel, body);
      const r = h.check();
      h.step(r.code === 1 && ok(strip(r.out)), msg, `exit ${r.code}\n${r.out}`);
      rm(rel);
    }
    put('app/reasoned.py', 'import json  # noqa: F401\n');
    const ok = h.check();
    h.step(ok.code === 0, 'a `# noqa: F401` that suppresses a real finding passes', ok.out);
    rm('app/reasoned.py');

    const orig = fs.readFileSync(path.join(dir, 'ruff.toml'));
    put('ruff.toml', '# forgot to extend the profile\n[lint]\nselect = ["F"]\n');
    let r = h.check();
    h.step(r.code === 1 && /FAIL \[python-base\/config\] ruff\.toml: does not set extend = "\.standards\/python-base\/ruff\.toml"/.test(r.out), 'a ruff.toml that does not extend the vendored config fails', r.out);
    rm('ruff.toml');
    r = h.check();
    h.step(r.code === 1 && /FAIL \[python-base\/config\] .*pyproject\.toml|FAIL \[python-base\/config\] no Ruff config/.test(r.out), 'a missing ruff.toml fails the config step', r.out);
    fs.writeFileSync(path.join(dir, 'ruff.toml'), orig);

    put('app/ruff.toml', '[lint]\nselect = ["F"]\n');
    r = h.check();
    h.step(r.code === 1 && /FAIL \[python-base\/config\] app\/ruff\.toml: nested Ruff config without `extend`/.test(r.out), 'a nested ruff.toml that does not extend fails, naming app/ruff.toml', r.out);
    put('app/ruff.toml', 'extend = "../ruff.toml"\n');
    r = h.check();
    h.step(r.code === 0, 'a nested ruff.toml that extends the root one passes', r.out);
    rm('app/ruff.toml');

    r = h.check();
    h.step(r.code === 0, 'check.mjs passes again after the injections are removed', r.out);
  },
};
